    bg = request.args.get('blood_group')
    sql = """SELECT bd.*, u.full_name, u.phone, u.profile_image
             FROM blood_donors bd JOIN users u ON u.id = bd.user_id
             WHERE bd.status = 'approved' AND bd.is_available = TRUE"""
